<?php namespace App\Http\Controllers; use App\Http\Requests\StoreProductRequest;use App\Http\Requests\UpdateProductRequest;use App\Models\Product;use Illuminate\Support\Facades\Storage; class ProductController extends Controller { public function index(){return view('products.index',['products'=>Product::latest()->paginate(15)]);}public function create(){return view('products.form',['product'=>new Product]);}public function store(StoreProductRequest $r){$d=$r->validated();if($r->hasFile('image'))$d['image']=$r->file('image')->store('products','public');Product::create($d);return redirect()->route('products.index')->with('success','Product created.');}public function edit(Product $product){return view('products.form',compact('product'));}public function update(UpdateProductRequest $r,Product $product){$d=$r->validated();if($r->hasFile('image')){$d['image']=$r->file('image')->store('products','public');} $product->update($d);return redirect()->route('products.index')->with('success','Product updated.');}public function destroy(Product $product){$product->delete();return back()->with('success','Product archived.');} }